'use strict';
const E=EntryAudit;
let entryErrors=[];
function entryDraft(){if(!intake.journey?.schema)intake.journey=E.fresh();return intake.journey;}
function entryInput(key,label,type='text',options=null){const f=entryDraft().fields;return `<label class="field">${esc(label)}${options?`<select data-entry-field="${key}">${[['','Selecione'],...options.map(v=>Array.isArray(v)?v:[v,v])].map(([v,l])=>`<option value="${esc(v)}" ${String(f[key])===v?'selected':''}>${esc(l)}</option>`).join('')}</select>`:`<input data-entry-field="${key}" type="${type}" value="${esc(f[key])}" ${type==='text'?'maxlength="180"':''}>`}</label>`;}
function entryChoice(key,label,options){return entryInput(key,label,'text',options);}
function entryPage(){
  const d=entryDraft();intake.dimension=route.dim;
  return `<nav class="breadcrumb"><a href="#auditoria/${route.dim}">${icon('back')} Voltar à Auditoria</a></nav><div class="heading"><div><h1>Adicionar à auditoria</h1><p>Encontre a operação e aproveite o que já está registrado.</p></div>${button('Salvar e sair','entry-save','','small')}</div>
  <nav class="entry-steps" aria-label="Etapas da entrada">${['Localizar operação','Conferir contexto','Reunir fontes','Escopo e início'].map((label,n)=>`<button data-action="entry-step" data-step="${n+1}" ${n+1>Math.max(d.step,d.furthest||1)?'disabled':''} ${d.step===n+1?'aria-current="step"':''}><span>${n+1}</span>${label}</button>`).join('')}</nav>
  <div class="entry-errors" role="alert" ${entryErrors.length?'':'hidden'}>${entryErrors.map(e=>`<p>${esc(e)}</p>`).join('')}</div>
  ${d.step===1?entryFind():`<div class="entry-bound"><div><strong>${esc(d.fields.supplier||'Operação externa')}</strong><span>${esc(d.fields.po||'PO não informada')} · ${d.opId?'Registro existente':d.recordKey?'Fonte demonstrativa localizada':'Novo registro'} · ${esc(d.fields.period)}</span></div>${button('Trocar vínculo','entry-step','data-step="1"','text small')}</div>${d.step===2?entryContext():d.step===3?entrySources():entryReview()}`}
  <div class="entry-footer"><span class="small muted">${d.savedAt?'Rascunho salvo nesta sessão.':'Alterações preservadas nesta sessão.'} Arquivos não são enviados.</span><div>${d.step>1?button('Voltar','entry-step',`data-step="${d.step-1}"`):''}${d.step>1&&d.step<4?button(d.step===2?'Continuar para fontes':'Revisar cobertura','entry-next','','primary'):d.step===4?button(d.opId?'Salvar complemento e abrir auditoria':'Salvar e acompanhar pendências','entry-finish','','primary'):''}</div></div>`;
}
function entryFind(){const d=entryDraft();return `<section class="panel"><div class="panel-body"><h2>Localizar cotação ou embarque</h2><p class="small muted">Busque primeiro para conservar vínculos e evitar um cadastro duplicado.</p><div class="entry-search"><label class="searchbox">${icon('search')}<input id="entry-search" type="search" value="${esc(d.query)}" placeholder="Cotação, processo, BL, booking, PO ou fornecedor" aria-label="Buscar cotação ou operação"></label><label class="entry-history"><input type="checkbox" id="entry-history" ${d.history?'checked':''}> Incluir concluídos / histórico</label></div><div class="presets entry-presets">${[['all','Tudo'],['operation','Operações auditadas'],['quote','Cotações sem embarque'],['shipment','Embarques sem cotação']].map(([v,l])=>`<button class="preset ${d.kind===v?'active':''}" data-action="entry-kind" data-kind="${v}" aria-pressed="${d.kind===v}">${l}</button>`).join('')}</div><div id="entry-results">${entryResults()}</div></div></section><div class="entry-external"><div><strong>A operação ainda não está cadastrada?</strong><p>Registre o contexto e traga as fontes disponíveis. Cotação e embarque podem ter origens diferentes.</p></div>${button('Cadastrar operação externa','entry-external')}</div><p class="small muted">Busca na amostra local, com cenários demonstrativos de cotação, embarque e acervo histórico. Consulta ao acervo real ainda não integrada.</p>`;}
function entryResults(){const d=entryDraft(),records=E.search(operations,d);return records.length?records.map(r=>`<article class="entry-result"><div><div class="entry-result-top">${badge(({operation:'Operação',quote:'Cotação aprovada',shipment:'Embarque',history:'Acervo histórico'})[r.kind])}${r.history?badge('Concluída'):''}${r.op||r.already?badge('Auditoria existente','blue'):''}</div><strong>${esc(r.title)}</strong><small>${esc(r.id)} · ${esc(r.po||'Sem PO')} · ${esc(r.route)}</small><small>${esc(r.reference)} · ${date(r.date)}${r.bl?' · '+esc(r.bl):''}</small></div><div class="entry-result-actions">${r.op||r.already?`<a class="btn small" href="${detailUrl(r.op||r.already,route.dim)}">Abrir auditoria</a>`:''}${button(r.op?'Completar fontes':r.already?'Rever vínculo':r.kind==='quote'?'Usar cotação':r.history?'Auditar esta operação':'Usar embarque','entry-select',`data-key="${esc(r.key)}"`,'small')}${r.history?button('Usar como base de nova operação','entry-base',`data-key="${esc(r.key)}"`,'text small'):''}</div></article>`).join(''):`<div class="empty"><h3>Nenhum registro neste recorte</h3><p>Confira a busca ou inclua operações concluídas. Você também pode cadastrar uma operação externa.</p></div>`;}
function entryManualContext(){const d=entryDraft(),f=d.fields,dupes=E.duplicates(operations,d);return `<form id="entry-context-form"><section class="panel"><div class="panel-head"><h2>Identificação e vínculo</h2><span class="small muted">BL pode ser informado depois</span></div><div class="panel-body form-grid">${entryInput('supplier','Fornecedor / exportador')}${entryInput('po','PO / referência do cliente')}${entryInput('bl','BL / AWB / documento, se emitido')}${entryInput('issuer','Emissor do documento de transporte')}${entryInput('booking','Booking, se disponível')}${entryInput('agent','Agente / prestador')}${entryChoice('shipmentOrigin','Registro do embarque',['Centrix','Externo','Ainda não registrado'])}${entryChoice('quoteOrigin','Origem da referência',['Centrix','Externa','Aguardando recebimento','Sem referência formal'])}${entryInput('quoteId','Cotação / versão / referência comercial')}${entryChoice('period','Momento da operação',['Em preparação','Em andamento','Concluída'])}${entryInput('operationDate','Data original da operação','date')}${entryChoice('paymentState','Situação do pagamento',['Não informado','A pagar','Pago','Parcial / com crédito'])}</div></section>
  ${dupes.length?`<div class="status-warning gap"><strong>Possível operação já cadastrada</strong><p>O documento ou booking coincide. Compare cliente, emissor e vínculos antes de criar outro registro.</p>${dupes.map(o=>button('Rever '+ref(o),'entry-select',`data-key="op:${esc(o.id)}"`,'small')).join('')}<label class="attachment"><input type="checkbox" data-entry-field="distinctConfirmed" ${f.distinctConfirmed?'checked':''}><span>Conferi: é outra operação, apesar da referência compartilhada.</span></label>${entryInput('distinctReason','Justificativa da operação distinta')}</div>`:''}
  <section class="panel gap"><div class="panel-head"><h2>Contexto da contratação</h2></div><div class="panel-body"><div class="form-grid">${entryChoice('direction','Direção',['Importação','Exportação'])}${entryChoice('modal','Modal',['Marítimo FCL','Marítimo LCL','Aéreo','Rodoviário','Multimodal'])}${entryInput('origin','Origem')}${entryInput('destination','Destino')}${entryChoice('incoterm','Incoterm',['EXW','FCA','FAS','FOB','CFR','CIF','CPT','CIP','DAP','DPU','DDP','NA'])}${entryInput('incotermVersion','Versão do Incoterm')}${entryInput('namedPlace','Local / porto nomeado')}${entryChoice('contractor','Quem contrata o frete principal?',['Vendedor / exportador','Comprador / cliente','Cliente exportador','Terceiro'])}${entryChoice('payment','Pagamento do frete',['Prepaid','Collect','Misto','Não confirmado'])}${entryInput('owner','Responsável interno pela auditoria')}</div><details class="entry-secondary"><summary>Carga e partes envolvidas</summary><div class="form-grid">${entryInput('importer','Importador / comprador')}${entryInput('exporter','Exportador / vendedor')}${entryInput('equipment','Equipamento / quantidade')}${entryInput('weight','Peso bruto / taxável')}${entryInput('volume','Volume / CBM')}${entryInput('finalPlace','Local final contratado')}</div></details><p class="small muted">Incoterm e prepaid/collect são confirmações independentes. Dados desconhecidos podem ficar em rascunho.</p><details class="entry-secondary"><summary>Participação da Freitas e justificativas</summary><div class="form-grid">${entryChoice('relation','Relação com a operação',['Participação operacional da Freitas','Somente auditoria'])}${entryInput('absenceReason','Justificativa de ausência / não aplicabilidade')}</div><p class="small muted">Somente auditoria é uma exceção. Não cria despacho ou acompanhamento do embarque.</p></details></div></section></form>`;}
function entrySources(){const d=entryDraft(),f=d.fields;return `<section class="panel"><div class="panel-head"><h2>O que você quer conferir?</h2></div><div class="panel-body scope-options">${[['both','Preço e performance'],['preco','Preço do frete'],['performance','Performance']].map(([v,l])=>`<label><input type="radio" name="entry-scope" data-entry-field="scope" value="${v}" ${f.scope===v?'checked':''}> ${l}</label>`).join('')}</div></section>
  <p class="tab-description">Fontes existentes são reaproveitadas. Acrescente o que falta e registre quem pode providenciar. Selecionar um arquivo não extrai nem confirma seu conteúdo nesta prévia.</p>
  ${d.sources.map(s=>`<details class="panel entry-source" data-entry-doc="${s.id}" ${(s.open??(s.id==='reference'&&!s.linked))?'open':''}><summary><div><strong>${esc(s.name)}</strong><small>${esc(s.help)}</small></div><div>${badge(E.requirement(s,f))}${badge(E.requirement(s,f)==='Não aplicável'?'Não aplicável':s.status,s.linked?'green':'blue')}</div></summary><div class="panel-body">${s.linked?`<p><strong>Fonte vinculada:</strong> ${s.files.map(esc).join(' · ')}</p><p class="small muted">Representação demonstrativa preservada. Novos arquivos serão complementos, sem substituir a referência existente.</p>`:''}<div class="form-grid"><label class="field">${s.linked?'Acrescentar arquivos':'Selecionar arquivos'}<input type="file" multiple data-entry-files="${s.id}" accept=".pdf,.png,.jpg,.jpeg,.xlsx,.csv,.eml,.txt"></label><label class="field">Disponibilidade<select data-entry-source="${s.id}" data-property="status" ${s.linked?'disabled':''}>${['Pendente','Arquivo selecionado','Indisponível','Substituto para revisão','Dispensa solicitada','Não aplicável',...(s.linked?['Vinculado']:[])].map(v=>`<option ${s.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Motivo / evidência alternativa<input data-entry-source="${s.id}" data-property="reason" value="${esc(s.reason)}" maxlength="300"></label><label class="field">De quem aguardamos / responsável<input data-entry-source="${s.id}" data-property="owner" value="${esc(s.owner)}" maxlength="120"></label><label class="field">Prazo conhecido<input type="date" data-entry-source="${s.id}" data-property="deadline" value="${esc(s.deadline)}"></label></div>${s.files.length?`<p class="small entry-file-list">${s.files.map(esc).join(' · ')}${s.linked?'':' · nomes salvos, conteúdo não enviado'}</p>`:''}${['Substituto para revisão','Dispensa solicitada'].includes(s.status)?'<p class="status-warning">Solicitação registrada para revisão. Não equivale a aprovação ou liberação dos controles dependentes.</p>':''}</div></details>`).join('')}
  <section class="panel gap"><div class="panel-head"><h2>Referência e aceite</h2></div><div class="panel-body"><p>Registre quem aprovou a condição comercial e onde está o aceite. A confirmação não altera automaticamente a referência de uma operação já auditada.</p>${f.quoteOrigin==='Sem referência formal'?entryInput('absenceReason','Motivo da ausência / fonte alternativa'):''}<div class="form-grid">${entryInput('referenceApprover','Aprovador comercial')}${entryInput('referenceDate','Data do aceite','date')}${entryInput('referenceEvidence','Documento / e-mail do aceite')}${entryInput('referenceNote','Condições ou alterações a revisar')}</div><details class="entry-secondary"><summary>Campos e condições da referência</summary><p class="small muted">Campos declarados para revisão; não foram extraídos dos arquivos e ainda não integram os cálculos.</p><div class="form-grid">${entryInput('referenceCurrency','Moeda de contratação')}${entryInput('referenceValidity','Validade da condição','date')}${entryInput('referenceService','Serviço / rota contratada')}${entryInput('referenceTransit','Transit time contratado')}${entryInput('referenceFreeTime','Free time contratado')}${entryInput('referenceEtd','ETD original','date')}${entryInput('referenceEta','ETA original','date')}${entryInput('referenceFx','PTAX / data-base / boletim / spread')}${entryInput('referenceBasis','Rubricas, unidades e bases de cálculo')}${entryInput('referenceTolerance','Regra / tolerância e vigência')}</div></details><label class="attachment"><input type="checkbox" data-entry-field="referenceConfirmed" ${f.referenceConfirmed?'checked':''}><span>Identifiquei a referência e a evidência do aceite.<small>Declaração local. Extração, revisão dos valores e congelamento produtivo ainda dependem de integração.</small></span></label><p class="small muted">Conferir a transcrição não cria aceite comercial. Regras de taxa, moeda, unidade, PTAX/data-base/spread e tolerância precisam vir da referência aplicável.</p></div></section>
  <section class="panel gap"><div class="panel-head"><h2>Cobranças da operação</h2>${button('Adicionar cobrança','entry-charge','','small')}</div><div class="panel-body">${d.charges.length?d.charges.map((c,n)=>`<div class="entry-edit-row"><div class="form-grid">${entryRowInput('charge',n,'id','Número da fatura / debit note',c.id)}${entryRowInput('charge',n,'issuer','Emissor',c.issuer)}${entryRowInput('charge',n,'currency','Moeda',c.currency)}${entryRowInput('charge',n,'due','Vencimento',c.due,'date')}${entryRowInput('charge',n,'original','Fatura original, se complemento/crédito',c.original)}${entryRowInput('charge',n,'note','Rubricas / base / pagamento a revisar',c.note)}</div>${button('Remover cobrança','entry-remove-charge',`data-index="${n}"`,'text small')}</div>`).join(''):'<p class="small muted">Adicione quantas cobranças existirem, separando emissor e documento. Uma fatura não cria outro embarque.</p>'}<p class="small muted">Valores e rubricas serão conferidos nas fontes. Estes identificadores não geram diferenças financeiras.</p></div></section>
  <section class="panel gap"><div class="panel-head"><h2>Marcos e eventos informados</h2>${button('Adicionar marco','entry-event','','small')}</div><div class="panel-body">${d.events.length?d.events.map((e,n)=>`<div class="entry-edit-row"><div class="form-grid">${entryRowInput('event',n,'name','Marco: partida, chegada, descarga…',e.name)}<label class="field">Natureza<select data-entry-row="event" data-index="${n}" data-property="kind">${['Compromisso original','Previsão revisada','Realizado'].map(v=>`<option ${e.kind===v?'selected':''}>${v}</option>`).join('')}</select></label>${entryRowInput('event',n,'date','Data',e.date,'date')}${entryRowInput('event',n,'source','Fonte / evidência',e.source)}</div>${button('Remover marco','entry-remove-event',`data-index="${n}"`,'text small')}</div>`).join(''):'<p class="small muted">Registre eventos externos e sua fonte, preservando o que era compromisso, previsão ou realizado.</p>'}<p class="small muted">Marcos declarados aguardam validação. Chegada ao porto não comprova descarga, disponibilidade ou entrega final.</p></div></section>`;}
function entryRowInput(kind,n,key,label,value,type='text'){return `<label class="field">${label}<input type="${type}" data-entry-row="${kind}" data-index="${n}" data-property="${key}" value="${esc(value)}" maxlength="180"></label>`;}
function entryReview(){const d=entryDraft(),f=d.fields,o=operations.find(o=>o.id===d.opId),fin=o?M.financial(o):null,perf=o?M.operational(o):null;return `<section class="panel"><div class="panel-head"><h2>Confira o que será registrado</h2>${badge(o?'Complemento da mesma operação':'Novo registro para auditoria','blue')}</div><div class="panel-body"><dl class="facts"><div><dt>Operação</dt><dd>${esc(f.direction)} · ${esc(f.modal)} · ${esc(f.origin)} → ${esc(f.destination)}</dd></div><div><dt>Contratação</dt><dd>${esc(f.incoterm)} ${esc(f.incotermVersion)} · ${esc(f.namedPlace)}<small>${esc(f.contractor)} · ${esc(f.payment)}</small></dd></div><div><dt>Vínculos</dt><dd>Referência: ${esc(f.quoteOrigin)} · embarque: ${esc(f.shipmentOrigin)}</dd></div><div><dt>Gestão</dt><dd>${esc(f.owner)} · ${esc(f.relation)}</dd></div><div><dt>Período original</dt><dd>${esc(f.period)} · ${date(f.operationDate)}</dd></div><div><dt>Identificadores</dt><dd>${esc(f.bl||'Documento ainda não emitido/informado')} · ${esc(f.booking||'Booking não informado')}</dd></div></dl></div></section>
  <div class="entry-coverage gap">${[['preco','Preço do frete',fin],['performance','Performance',perf]].map(([dim,label,r])=>`<section class="panel"><div class="panel-head"><h2>${label}</h2></div><div class="panel-body">${f.scope!=='both'&&f.scope!==dim?`${badge('Fora do recorte solicitado')}<p>${o?'Resultados existentes permanecem preservados.':'Não será iniciada nesta dimensão.'}</p>`:r?`${badge('Resultado existente preservado','blue')}<p>${dim==='preco'?r.checked.length+'/'+r.invoices.length+' cobranças com valores disponíveis':r.evaluated.length+'/'+(r.applicable?.length||r.checks.length)+' controles aplicáveis verificados'}.</p><p>Novos documentos e declarações aguardam validação. Não substituem esta base automaticamente.</p>`:`${badge('Aguardando fontes validadas','blue')}<p>${dim==='preco'?'Referência aceita, faturas comparáveis e regras por rubrica/câmbio.':'Compromissos e eventos reais sustentados pelas fontes.'}</p><p>A seleção de arquivos e o preenchimento do contexto não executam a auditoria.</p>`}</div></section>`).join('')}</div>
  <section class="panel gap"><div class="panel-head"><h2>Fontes e próximos passos</h2><span class="small muted">${d.charges.length} cobranças · ${d.events.length} marcos informados</span></div><div class="panel-body">${d.sources.filter(s=>E.requirement(s,f)!=='Fora do recorte'&&E.requirement(s,f)!=='Opcional').map(s=>`<div class="entry-pending-row"><div><strong>${esc(s.name)}</strong><small>${esc(E.requirement(s,f))} · ${esc(s.reason||s.help)}</small></div><div>${badge(E.requirement(s,f)==='Não aplicável'?'Não aplicável':s.linked?'Vinculado':s.status==='Arquivo selecionado'?'Aguardando leitura':s.status,s.linked?'green':'blue')}<small>${s.linked?'Fonte já vinculada':E.requirement(s,f)==='Não aplicável'?'Fora do escopo desta operação':esc(s.owner||'Responsável pela fonte a definir')+(s.deadline?' · '+date(s.deadline):' · sem prazo confirmado')}</small></div></div>`).join('')}</div></section>
  <div class="intro-note gap">${f.period==='Concluída'?'Esta operação permanece concluída. A auditoria será registrada agora, usando as condições e fontes da época; o embarque não será reaberto. ':''}${f.paymentState==='Pago'?'Auditoria posterior ao pagamento: diferença identificada não é crédito ou valor recuperado. ':''}Nesta prévia, fontes complementares aguardam leitura e validação. Nenhum arquivo será enviado, documento dispensado ou mensagem disparada.</div>`;}
function entryManagement(op){if(!op.entryContext)return '';const f=op.entryContext;return `<section class="panel gap entry-management"><div class="panel-head"><h2>Entrada e pendências da operação</h2>${button('Completar contexto e fontes','entry-resume',`data-id="${esc(op.id)}"`,'small')}</div><div class="panel-body"><div class="entry-management-line"><span><strong>${esc(f.owner)}</strong> · responsável pela auditoria</span><span>${esc(f.period)} · operação de ${date(f.operationDate)}</span></div><p class="small">Referência ${esc(f.quoteOrigin)} · embarque ${esc(f.shipmentOrigin)} · ${esc(f.relation)}. ${f.paymentState==='Pago'?'Fatura paga: auditoria posterior ao pagamento.':''}</p><p class="small muted">Arquivos selecionados e dados declarados aguardam validação. Resultados anteriores preservados.</p>${op.entryCharges?.length?`<details class="entry-secondary"><summary>${op.entryCharges.length} cobranças informadas para revisão</summary>${op.entryCharges.map(c=>`<p><strong>${esc(c.id)}</strong> · ${esc(c.issuer)} · ${esc(c.currency)} · ${c.due?'vencimento '+date(c.due):'sem vencimento informado'}<br>${esc(c.original?'Vínculo: '+c.original+' · ':'')}${esc(c.note||'Rubricas aguardando leitura')}</p>`).join('')}</details>`:''}${op.entryEvents?.length?`<details class="entry-secondary"><summary>${op.entryEvents.length} marcos declarados, ainda não validados</summary>${op.entryEvents.map(e=>`<p><strong>${esc(e.name)}</strong> · ${esc(e.kind)} · ${date(e.date)}<br>Fonte: ${esc(e.source)}</p>`).join('')}</details>`:''}${(op.entrySources||[]).filter(s=>!s.linked&&E.requirement(s,f)!=='Não aplicável'&&E.requirement(s,f)!=='Fora do recorte'&&E.requirement(s,f)!=='Opcional').map(s=>`<div class="entry-pending-row"><div><strong>${esc(s.name)}</strong><small>${esc(s.reason||s.help)}</small>${s.files.length?`<small>${s.files.map(esc).join(' · ')} · arquivos não enviados</small>`:''}</div><div>${badge(s.status,'blue')}<small>${esc(s.owner||'Responsável a definir')} · ${s.deadline?date(s.deadline):'Sem prazo confirmado'}</small></div></div>`).join('')}</div></section>`;}
function entryRender(){persist();render();$('#main')?.focus({preventScroll:true});}
document.addEventListener('click',event=>{
  const b=event.target.closest('[data-action^="entry-"]');if(!b)return;event.preventDefault();const d=entryDraft();entryErrors=[];
  switch(b.dataset.action){
    case 'entry-kind':d.kind=b.dataset.kind;entryRender();break;
    case 'entry-external':intake.journey=E.fresh();intake.journey.step=2;entryRender();break;
    case 'entry-select':{const r=E.catalogue(operations).find(r=>r.key===b.dataset.key);intake.journey=E.select(r);entryRender();break;}
    case 'entry-base':{const r=E.catalogue(operations).find(r=>r.key===b.dataset.key);const n=E.fresh();n.step=2;n.fields.supplier=r.title;n.fields.agent=r.agent;[n.fields.origin,n.fields.destination]=r.route.split(' → ');intake.journey=n;entryRender();toast('Nova operação: identificadores, aceite, documentos e eventos antigos não foram copiados.');break;}
    case 'entry-step':{const target=Number(b.dataset.step),max=Math.max(d.step,d.furthest||1);if(target<=max){if(target>2)entryErrors=E.errors(d,2);if(target>3)entryErrors.push(...E.errors(d,3));if(!entryErrors.length){d.furthest=max;d.step=target;}entryRender();}break;}
    case 'entry-next':entryErrors=E.errors(d,d.step);if(d.step===2&&E.duplicates(operations,d).length&&(!d.fields.distinctConfirmed||!d.fields.distinctReason?.trim()))entryErrors.push('Revise a possível duplicidade abaixo antes de continuar.');if(!entryErrors.length){d.step++;d.furthest=Math.max(d.step,d.furthest||1);}entryRender();window.scrollTo(0,0);break;
    case 'entry-save':d.savedAt=new Date().toISOString();persist();location.hash='#auditoria/'+route.dim;toast('Rascunho da entrada salvo nesta sessão.');break;
    case 'entry-charge':d.charges.push({id:'',issuer:'',currency:'USD',due:'',original:'',note:''});entryRender();break;
    case 'entry-event':d.events.push({name:'',kind:'Realizado',date:'',source:''});entryRender();break;
    case 'entry-remove-charge':d.charges.splice(Number(b.dataset.index),1);entryRender();break;
    case 'entry-remove-event':d.events.splice(Number(b.dataset.index),1);entryRender();break;
    case 'entry-finish':{const r=E.create(operations,d,new Date().toLocaleDateString('sv-SE'));if(r.errors.length){entryErrors=r.errors;entryRender();window.scrollTo(0,0);return;}P.enrich(F.enrich(operations));intake.journey=E.fresh();persist();location.hash=detailUrl(r.op,r.op.requested.includes(route.dim)?route.dim:r.op.requested[0]);toast(r.existing?'Complemento registrado; resultados e histórico preservados.':'Operação registrada. Fontes aguardando validação.');break;}
    case 'entry-resume':intake.journey=E.select(E.catalogue(operations).find(r=>r.key==='op:'+b.dataset.id));location.hash='#auditoria/entrada/'+route.dim;persist();break;
  }
});
document.addEventListener('input',event=>{
  const t=event.target,d=entryDraft();if(t.id==='entry-search'){d.query=t.value;$('#entry-results').innerHTML=entryResults();persist();return;}
  if(t.dataset.entryField){d.fields[t.dataset.entryField]=t.type==='checkbox'?t.checked:t.value;persist();}
  if(t.dataset.entrySource){d.sources.find(s=>s.id===t.dataset.entrySource)[t.dataset.property]=t.value;persist();}
  if(t.dataset.entryRow){d[t.dataset.entryRow==='charge'?'charges':'events'][Number(t.dataset.index)][t.dataset.property]=t.value;persist();}
});
document.addEventListener('change',event=>{
  const t=event.target,d=entryDraft();
  if(t.id==='entry-history'){d.history=t.checked;entryRender();}
  if(t.dataset.entryFiles){const s=d.sources.find(s=>s.id===t.dataset.entryFiles);s.files=[...new Set([...s.files,...[...t.files].map(f=>f.name)])];if(!s.linked)s.status=s.files.length?'Arquivo selecionado':'Pendente';entryRender();}
  if(t.dataset.entrySource&&t.dataset.property==='status'){d.sources.find(s=>s.id===t.dataset.entrySource).status=t.value;entryRender();}
  if(t.dataset.entryField&&['scope','quoteOrigin'].includes(t.dataset.entryField)){d.fields[t.dataset.entryField]=t.value;entryRender();}
});

document.addEventListener('toggle',event=>{const t=event.target;if(t.dataset?.entryDoc){const s=entryDraft().sources.find(s=>s.id===t.dataset.entryDoc);if(s){s.open=t.open;persist();}}},true);
document.addEventListener('submit',event=>{if(event.target.id==='entry-context-form')event.preventDefault();});
